import{_ as t,o,c as n,a2 as s}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Meeting mode","description":"","frontmatter":{},"headers":[],"relativePath":"guide/meeting.md","filePath":"guide/meeting.md","lastUpdated":1792982028000}'),a={name:"guide/meeting.md"};function r(i,e,h,l,d,c){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="meeting-mode" tabindex="-1">Meeting mode <a class="header-anchor" href="#meeting-mode" aria-label="Permalink to &quot;Meeting mode&quot;">​</a></h1><p>This page explains how MeetCue follows a live meeting: when it shows hints, how it handles several questions in a row, and how to read the panel.</p><h2 id="start-and-pause-listening" tabindex="-1">Start and pause listening <a class="header-anchor" href="#start-and-pause-listening" aria-label="Permalink to &quot;Start and pause listening&quot;">​</a></h2><p>Press <code>Ctrl+Alt+Space</code>, or click <strong>Start</strong> on the panel. The status dot turns green and the timer starts. Press the shortcut again to pause; nothing is sent to any provider while paused.</p><p>You can also start and pause from the tray icon menu.</p><h2 id="how-a-question-becomes-hints" tabindex="-1">How a question becomes hints <a class="header-anchor" href="#how-a-question-becomes-hints" aria-label="Permalink to &quot;How a question becomes hints&quot;">​</a></h2><ol><li><strong>Recognition</strong>: both audio sources are streamed to your speech recognition provider. Only sound that contains speech is sent; silence is skipped, apart from a short keep-alive signal.</li><li><strong>Detection</strong>: when another participant finishes a sentence, the detection model decides whether it&#39;s a question for you. Your own microphone is never checked for questions.</li><li><strong>Hints</strong>: for a question, the hint model writes three to five numbered talking points and a short sample answer. Points appear one by one as they are generated.</li></ol><p>With <strong>Early trigger</strong> on (<strong>Settings › Hints</strong>), MeetCue starts generating as soon as the speaker pauses for a moment, before the sentence is officially over. If the speaker keeps going and the question changes noticeably, the early request is cancelled and a new one starts. This saves several hundred milliseconds on most questions.</p><h2 id="read-the-panel" tabindex="-1">Read the panel <a class="header-anchor" href="#read-the-panel" aria-label="Permalink to &quot;Read the panel&quot;">​</a></h2><p>From top to bottom, the full panel shows:</p><ol><li><strong>Title bar</strong>: status, elapsed time, pause, keep on top, and the switch to the mini bar.</li><li><strong>Sources</strong>: a level meter for your microphone and one for system sound. They move as soon as the panel is shown, before you start, so you can check that MeetCue hears you. Nothing is sent to any provider until you start.</li><li><strong>Question queue</strong>: the previous, current and next question, with their status. Click a card to scroll to that question.</li><li><strong>Conversation</strong>: one block per question. Click the grey question text to see the sentences around it and why it was detected. <strong>Show full answer</strong> expands the sample answer.</li><li><strong>Footer</strong>: shortcut reminders and the latency of the last hint.</li></ol><p>The <strong>mini bar</strong> (<code>Ctrl+Alt+H</code>) shows only the current question, its progress, the next point to cover in large type, and how many questions are waiting.</p><h2 id="coverage-ticks" tabindex="-1">Coverage ticks <a class="header-anchor" href="#coverage-ticks" aria-label="Permalink to &quot;Coverage ticks&quot;">​</a></h2><p>With <strong>Track what I&#39;ve said</strong> on, MeetCue compares what you say with the talking points. A point you&#39;ve covered gets a green tick and dims, and the next uncovered point is marked <strong>Next</strong>. Matching uses words for English and character pairs for Chinese, so paraphrasing a point closely is enough.</p><p>If you use speakers instead of headphones, your microphone also hears the other participants. MeetCue ignores microphone text that closely matches what was just played, so their words don&#39;t tick off your points.</p><h2 id="several-questions-at-once" tabindex="-1">Several questions at once <a class="header-anchor" href="#several-questions-at-once" aria-label="Permalink to &quot;Several questions at once&quot;">​</a></h2><ul><li><strong>Queue interruptions</strong> (on by default): a question asked while you are answering waits as <strong>Next</strong>. When you finish answering, it becomes the current question.</li><li>A question asked while you are not speaking replaces the current one, which moves to <strong>Previous</strong>.</li><li>Use <code>Ctrl+Alt+[</code> and <code>Ctrl+Alt+]</code> to move between questions, and <code>Ctrl+Alt+Enter</code> to mark the current one answered.</li></ul><p>A question counts as answered only after you have spoken and then stopped, so silence before your answer never archives it.</p><h2 id="hide-the-panel-from-screen-sharing" tabindex="-1">Hide the panel from screen sharing <a class="header-anchor" href="#hide-the-panel-from-screen-sharing" aria-label="Permalink to &quot;Hide the panel from screen sharing&quot;">​</a></h2><p><strong>Hide the panel when sharing the screen</strong> is on by default. Teams, Zoom, browser screen sharing and most recording tools then capture the area behind the panel instead of the panel itself.</p><div class="warning custom-block"><p class="custom-block-title">Not a guarantee</p><p>Some recording methods and external capture hardware can still capture the panel. Test with your meeting app before relying on it.</p></div><h2 id="cost-during-a-meeting" tabindex="-1">Cost during a meeting <a class="header-anchor" href="#cost-during-a-meeting" aria-label="Permalink to &quot;Cost during a meeting&quot;">​</a></h2><p>Each call&#39;s usage is recorded and converted with the downloaded price list; calls to models without a price are counted but not costed. <strong>Settings › Providers &amp; cost</strong> shows this month&#39;s usage by provider. You can set a per-meeting and a monthly budget; MeetCue warns at 80% and, at 100%, only notifies you, pauses hints or ends the session, as you choose.</p>',23)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
